package com.investinator.knowledge;
import static com.investinator.domain.Json.*;
import com.investinator.domain.Json;
import com.investinator.persistence.*;
import com.investinator.workflows.WorkflowService;
import com.investinator.domain.Contracts.Lifecycle;
import com.investinator.correlation.CorrelationService;
import com.investinator.chat.InvestigationAnswer;
import com.investinator.api.ApiFailure;
import org.springframework.stereotype.Service;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import java.util.*;
@Service @ConditionalOnProperty(name="investinator.persistence.enabled",havingValue="true")
public class KnowledgeService {
    private final Store db;private final WorkflowService workflows;private final CorrelationService correlations;private final KnowledgeIndex index;
    public KnowledgeService(Store db,WorkflowService workflows,CorrelationService correlations,KnowledgeIndex index,org.springframework.core.env.Environment env){String write=env.getProperty("KNOWLEDGE_WRITE_TOKEN", ""),review=env.getProperty("KNOWLEDGE_REVIEW_TOKEN", ""),feedback=env.getProperty("KNOWLEDGE_FEEDBACK_TOKEN", "");if(!review.isBlank()&&(review.equals(write)||review.equals(feedback)))throw new IllegalArgumentException("Knowledge ingestion and review require distinct credentials");this.db=db;this.workflows=workflows;this.correlations=correlations;this.index=index;}
    public record Outcome(String incident_id,String decision,String claimed_cause,Boolean repair_worked,List<String> evidence_ids) {
        public Outcome {if(incident_id==null||!Set.of("ACCEPTED","REJECTED","CONFIRMED").contains(decision)||claimed_cause==null||claimed_cause.isBlank()||claimed_cause.length()>3000||evidence_ids==null||evidence_ids.size()>100)throw new IllegalArgumentException("Invalid outcome feedback");claimed_cause=com.investinator.security.Redaction.redact(claimed_cause);evidence_ids=List.copyOf(evidence_ids);}
    }
    public record SearchScope(String technology,String version,String mode) {}
    public SearchScope scope(String tenant,String incident){var item=workflows.incident(tenant,incident);String technology=item.technology.name(),version="UNKNOWN",mode="UNKNOWN";try{var graph=correlations.boundGraph(tenant,incident);mode=graph.metadata_mode();var technologyMatch=java.util.regex.Pattern.compile("(?i)^(Kafka|HDFS|Kudu|NiFi|Spark|Hive|YARN|Airflow|Impala)\\b").matcher(graph.platform_version());if(technologyMatch.find())technology=Map.of("kafka","Kafka","hdfs","HDFS","kudu","Kudu","nifi","NiFi","spark","Spark","hive","Hive","yarn","YARN","airflow","Airflow","impala","Impala").get(technologyMatch.group().toLowerCase(Locale.ROOT));var match=java.util.regex.Pattern.compile("[0-9]+(?:\\.[0-9]+)*").matcher(graph.platform_version());if(match.find())version=match.group();}catch(ApiFailure ignored){}return new SearchScope(technology,version,mode);}
    public Map<String,Object> ingest(String tenant,String actor,KnowledgeDocument document) {
        if(document.acl_principals().stream().anyMatch(p->!p.matches(java.util.regex.Pattern.quote(tenant)+"\\.[A-Za-z0-9_.-]{1,120}")))throw new ApiFailure(422,"Knowledge ACL principals must belong to the server-bound tenant");
        return db.write(tenant,()->{
            if(document.source_type()==KnowledgeDocument.Kind.RESOLVED_POSTMORTEM||document.source_type()==KnowledgeDocument.Kind.VALIDATED_CORRECTIVE_ACTION){if(document.incident_id()==null||workflows.incident(tenant,document.incident_id()).status!=Lifecycle.resolved)throw new ApiFailure(409,"Only independently verified resolved incidents are eligible");}
            if(document.source_type()==KnowledgeDocument.Kind.VALIDATED_CORRECTIVE_ACTION&&(db.select(Table.EXECUTION_RECORDS,tenant,"incident_id=?",document.incident_id()).isEmpty()||document.feedback_id()==null))throw new ApiFailure(409,"Validated action requires execution, recovery verification and reviewed outcome");
            if(document.source_type()==KnowledgeDocument.Kind.TOPOLOGY_SNAPSHOT){if(document.graph_id()==null||document.graph_revision()==null)throw new ApiFailure(422,"Topology source must reference a stored revision");correlations.graph(tenant,document.graph_id(),document.graph_revision());}
            if(document.feedback_id()!=null){var outcome=outcome(tenant,document.feedback_id());var body=Json.decode(encode(outcome.get("payload")),Outcome.class);if(document.incident_id()!=null&&!document.incident_id().equals(body.incident_id))throw new ApiFailure(422,"Outcome belongs to another incident");if(!"APPROVED".equals(outcome.get("review_state"))||!body.decision.equals("CONFIRMED")||!Boolean.TRUE.equals(body.repair_worked))throw new ApiFailure(409,"Rejected/unreviewed claims cannot become validated knowledge");}
            var old=rows(tenant,document.document_id(),document.revision());if(!old.isEmpty()){if(!old.getFirst().get("content_hash").equals(document.hash()))throw new ApiFailure(409,"Knowledge revision is immutable");return metadata(old.getFirst());}
            String state=document.quarantined()?"QUARANTINED":"PENDING_REVIEW";db.jdbc.update("insert into knowledge_revisions(tenant_id,document_id,revision,content_hash,payload,review_state,submitted_by) values(?,?,?,?,?::jsonb,?,?)",tenant,document.document_id(),document.revision(),document.hash(),encode(document),state,actor);workflows.audit(tenant,"knowledge_draft_ingested",document.incident_id(),actor,obj("document_id",document.document_id(),"revision",document.revision(),"review_state",state));return metadata(rows(tenant,document.document_id(),document.revision()).getFirst());
        });
    }
    public Map<String,Object> review(String tenant,String actor,String id,int revision,String decision,String reason){if(!Set.of("APPROVE","REJECT","REVOKE").contains(decision)||reason==null||reason.strip().length()<10||reason.length()>2000)throw new ApiFailure(422,"Review decision and meaningful reason required");return db.write(tenant,()->{var row=required(tenant,id,revision);if(actor.equals(row.get("submitted_by")))throw new ApiFailure(403,"Independent reviewer required");String previous=row.get("review_state").toString();if(decision.equals("APPROVE")&&!previous.equals("PENDING_REVIEW"))throw new ApiFailure(409,"Only non-quarantined pending drafts can be approved");if(decision.equals("REJECT")&&!Set.of("PENDING_REVIEW","QUARANTINED").contains(previous))throw new ApiFailure(409,"Approved revisions require explicit revocation");if(decision.equals("REVOKE")&&!previous.equals("APPROVED"))throw new ApiFailure(409,"Only approved revisions can be revoked");String state=decision.equals("APPROVE")?"APPROVED":decision.equals("REVOKE")?"REVOKED":"REJECTED";db.jdbc.update("update knowledge_revisions set review_state=?,reviewed_by=?,reviewed_at=now(),indexed=false where tenant_id=? and document_id=? and revision=?",state,actor,tenant,id,revision);epoch(tenant);workflows.audit(tenant,"knowledge_review",null,actor,obj("document_id",id,"revision",revision,"decision",decision,"reason",com.investinator.security.Redaction.redact(reason)));return metadata(required(tenant,id,revision));});}
    public Map<String,Object> publish(String tenant,String actor,String id,int revision){var row=required(tenant,id,revision);if(!"APPROVED".equals(row.get("review_state")))throw new ApiFailure(409,"Unreviewed or revoked knowledge cannot be published");db.jdbc.update("update knowledge_revisions set indexed=false where tenant_id=? and document_id=? and revision=?",tenant,id,revision);var document=document(row);index.publish(document.chunks(tenant));return db.write(tenant,()->{var current=required(tenant,id,revision);if(!"APPROVED".equals(current.get("review_state")))throw new ApiFailure(409,"Review state changed during indexing; retrieval remains fail-closed");db.jdbc.update("update knowledge_revisions set indexed=true where tenant_id=? and document_id=? and revision=?",tenant,id,revision);workflows.audit(tenant,"knowledge_published",document.incident_id(),actor,obj("document_id",id,"revision",revision,"hash",document.hash()));return metadata(required(tenant,id,revision));});}
    public Map<String,Object> draft(String tenant,String id,int revision){var row=required(tenant,id,revision);var document=document(row);return obj("metadata",metadata(row),"document",document,"related_outcomes",document.incident_id()==null?List.of():outcomes(tenant,document.incident_id()));}
    public Map<String,Object> readableDocument(String tenant,String principal,String id,int revision){var row=required(tenant,id,revision);var document=document(row);Integer latest=db.jdbc.queryForObject("select max(revision) from knowledge_revisions where tenant_id=? and document_id=? and review_state in ('APPROVED','REVOKED')",Integer.class,tenant,id);if(!"APPROVED".equals(row.get("review_state"))||latest==null||latest!=revision||!document.acl_principals().contains(principal))throw new ApiFailure(403,"Knowledge revision is not readable in this scope");return obj("metadata",metadata(row),"document",document,"evidence_kind","HISTORICAL_ADVICE");}
    public Map<String,Object> search(String tenant,String principal,String text,SearchScope scope) {
        var found=index.search(tenant,principal,text,scope.technology,scope.version,scope.mode);var verified=new ArrayList<Map<String,Object>>();int rejected=0;
        for(var hit:found.hits())try {
            var raw=hit.document();String doc=raw.get("document_id").toString();int rev=((Number)raw.get("revision")).intValue();var chunk=authorizeChunk(tenant,principal,doc,rev,raw.get("chunk_id").toString(),scope);if(chunk==null||!Objects.equals(raw.get("tenant_id"),tenant)||!Objects.equals(raw.get("content_hash"),chunk.get("content_hash"))||!Objects.equals(raw.get("text"),chunk.get("text"))){rejected++;continue;}
            var item=new LinkedHashMap<>(chunk);double score=hit.score()+(scope.version.equals(item.get("platform_version"))?3:0)+(scope.mode.equals(item.get("metadata_mode"))?3:0);item.put("rank_score",score);item.put("evidence_kind","HISTORICAL_ADVICE");item.put("reference","knowledge:"+doc+"@"+rev+"#"+item.get("chunk_index"));verified.add(item);
        }catch(Exception ignored){rejected++;}
        verified.sort(Comparator.<Map<String,Object>>comparingDouble(v->((Number)v.get("rank_score")).doubleValue()).reversed().thenComparing(v->v.get("chunk_id").toString()));var unique=new LinkedHashMap<String,Map<String,Object>>();for(var item:verified)unique.putIfAbsent(item.get("document_id")+":"+item.get("revision"),item);
        long pending=db.jdbc.queryForObject("select count(*) from knowledge_revisions where tenant_id=? and review_state='APPROVED' and not indexed",Long.class,tenant);String status=found.status();if(status.equals("HEALTHY")&&(rejected>0||pending>0))status="DEGRADED";
        return obj("status",status,"retrieval_mode",Set.of("HEALTHY","DEGRADED").contains(found.status())?"LIVE":"NOT_TESTED","source_mode","HISTORICAL_ADVICE","items",unique.values().stream().limit(5).toList(),"rejected_records",rejected,"pending_index_revisions",pending,"partial",found.partial()||rejected>0||pending>0,"ranking","BM25 plus version/mode specificity; no vectors or embeddings");
    }
    private Map<String,Object> authorizeChunk(String tenant,String principal,String id,int revision,String chunkId,SearchScope scope){
        var candidates=rows(tenant,id,revision);if(candidates.isEmpty())return null;var row=candidates.getFirst();if(!row.get("review_state").equals("APPROVED"))return null;
        var document=document(row);if(!document.acl_principals().contains(principal)||!document.technology().equals(scope.technology)||!(document.platform_version().equals("ANY")||scope.version.equals(document.platform_version())||scope.version.startsWith(document.platform_version()+"."))||!(document.metadata_mode().equals("ANY")||scope.mode.equals(document.metadata_mode())))return null;
        Integer latest=db.jdbc.queryForObject("select max(revision) from knowledge_revisions where tenant_id=? and document_id=? and review_state in ('APPROVED','REVOKED')",Integer.class,tenant,id);if(latest==null||latest!=revision)return null;
        return document.chunks(tenant).stream().filter(c->c.get("chunk_id").equals(chunkId)).findFirst().orElse(null);
    }
    public boolean citationAllowed(String tenant,String principal,String incident,InvestigationAnswer.Citation citation,String id,int revision){if(!citation.kind().equals("HISTORICAL_ADVICE")||incident==null)return false;var chunk=authorizeChunk(tenant,principal,id,revision,citation.evidence_id(),scope(tenant,incident));return chunk!=null&&citation.source().equals("knowledge:"+id+"@"+revision+"#"+chunk.get("chunk_index"))&&Objects.equals(citation.observed_at(),chunk.get("source_time"));}
    public String feedback(String tenant,String actor,Outcome input){return db.write(tenant,()->{var item=workflows.incident(tenant,input.incident_id);var ids=new HashSet<String>();item.evidence.forEach(e->ids.add(e.id()));correlations.observations(tenant,input.incident_id).forEach(e->ids.add(e.id()));db.jdbc.queryForList("select evidence_id from citation_evidence where tenant_id=? and incident_id=?",String.class,tenant,input.incident_id).forEach(ids::add);if(!ids.containsAll(input.evidence_ids)||input.decision.equals("CONFIRMED")&&input.evidence_ids.isEmpty())throw new ApiFailure(422,"Outcome requires verifiable incident evidence");String id=id();db.jdbc.update("insert into knowledge_outcomes(tenant_id,id,incident_id,payload,submitted_by) values(?,?,?,?::jsonb,?)",tenant,id,input.incident_id,encode(input),actor);workflows.audit(tenant,"knowledge_outcome_submitted",input.incident_id,actor,obj("outcome_id",id,"decision",input.decision,"automatic_knowledge_update",false));return id;});}
    public Map<String,Object> reviewOutcome(String tenant,String actor,String id,String decision,String reason){if(!Set.of("APPROVE","REJECT").contains(decision)||reason==null||reason.length()<10)throw new ApiFailure(422,"Feedback review required");return db.write(tenant,()->{var row=outcome(tenant,id);if(actor.equals(row.get("submitted_by")))throw new ApiFailure(403,"Independent reviewer required");if(!row.get("review_state").equals("PENDING_REVIEW"))throw new ApiFailure(409,"Outcome already reviewed");String state=decision.equals("APPROVE")?"APPROVED":"REJECTED";db.jdbc.update("update knowledge_outcomes set review_state=?,reviewed_by=?,reviewed_at=now() where tenant_id=? and id=?",state,actor,tenant,id);epoch(tenant);workflows.audit(tenant,"knowledge_outcome_reviewed",row.get("incident_id").toString(),actor,obj("outcome_id",id,"decision",decision,"reason",com.investinator.security.Redaction.redact(reason),"automatic_knowledge_update",false));return obj("id",id,"review_state",state,"automatic_knowledge_update",false);});}
    public List<Map<String,Object>> outcomes(String tenant,String incident){workflows.incident(tenant,incident);return db.jdbc.queryForList("select id,payload::text,review_state,submitted_by,reviewed_by,reviewed_at,created_at from knowledge_outcomes where tenant_id=? and incident_id=? order by created_at desc limit 50",tenant,incident).stream().map(r->obj("id",r.get("id"),"user_report",Json.decode(r.get("payload").toString()),"review_state",r.get("review_state"),"submitted_by",r.get("submitted_by"),"reviewed_by",r.get("reviewed_by"),"reviewed_at",Objects.toString(r.get("reviewed_at"),null),"created_at",r.get("created_at").toString(),"source_mode","HISTORICAL_USER_REPORT")).toList();}
    public String policyEpoch(String tenant){var rows=db.jdbc.queryForList("select version from knowledge_epochs where tenant_id=?",Long.class,tenant);return rows.isEmpty()?"0":rows.getFirst().toString();}
    private void epoch(String tenant){db.jdbc.update("insert into knowledge_epochs(tenant_id,version) values(?,1) on conflict(tenant_id) do update set version=knowledge_epochs.version+1",tenant);}
    private Map<String,Object> outcome(String tenant,String id){var rows=db.jdbc.queryForList("select *,payload::text as body from knowledge_outcomes where tenant_id=? and id=?",tenant,id);if(rows.isEmpty())throw new ApiFailure(404,"Outcome not found");var row=new LinkedHashMap<>(rows.getFirst());row.put("payload",Json.decode(row.get("body").toString()));return row;}
    private List<Map<String,Object>> rows(String tenant,String id,int revision){return db.jdbc.queryForList("select document_id,revision,content_hash,payload::text as body,review_state,submitted_by,reviewed_by,indexed from knowledge_revisions where tenant_id=? and document_id=? and revision=?",tenant,id,revision);}
    private Map<String,Object> required(String tenant,String id,int revision){var rows=rows(tenant,id,revision);if(rows.isEmpty())throw new ApiFailure(404,"Knowledge revision not found");return rows.getFirst();}
    private KnowledgeDocument document(Map<String,Object> row){return Json.decode(row.get("body").toString(),KnowledgeDocument.class);}
    private Map<String,Object> metadata(Map<String,Object> row){return obj("document_id",row.get("document_id"),"revision",row.get("revision"),"content_hash",row.get("content_hash"),"review_state",row.get("review_state"),"submitted_by",row.get("submitted_by"),"reviewed_by",row.get("reviewed_by"),"indexed",row.get("indexed"));}
}
